import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { MisCompras } from '../models/mis-compras';

@Injectable({
  providedIn: 'root'
})
export class MisComprasService {
  private apiUrl = 'http://localhost:3000/api/compras';

  constructor(private http: HttpClient) { }

  //este no lo usamos de momento, seria para el panel admin
  /*obtenerCompras(): Observable<MisCompras[]> {
    return this.http.get<MisCompras[]>(`${this.apiUrl}`);
  }*/

  obtenerComprasUsuario(emailUser: string): Observable<MisCompras[]> {
    const params = { emailUsuario : emailUser}
    return this.http.get<MisCompras[]>(`${this.apiUrl}/usuario`, {params});
  }

  crearCompra(carrito: Carrito): Observable<MisCompras> {
    const compra: MisCompras = {
      emailUsuario: carrito.emailUsuario,
      numPedido: '', // Puedes generar un número de pedido aquí
      productos: carrito.productos.map(producto => ({
        idCompra: 0, // Puedes dejarlo en 0 y que el backend lo gestione
        nombreProd: producto.nombreProd,
        cantidad: producto.cantidad,
        precio: producto.precio,
        totalProd: producto.cantidad * producto.precio
      })),
      total: carrito.total
    };

    return this.http.post<MisCompras>(`${this.apiUrl}`, compra);
  }
}
